INSERT INTO public.prompts (slug, title, category, description, body, is_featured, is_published, sort_order) VALUES
('brand-identity-blueprint', 'Brand Identity Blueprint', 'Marketing & Brand Strategy', 'Define your brand voice, visual identity, and positioning in one comprehensive document.', 'Act as a senior brand strategist. Create a complete brand identity blueprint for my business, {{business_name}}, which {{business_description}}. Our target audience is {{target_audience}} and our main competitors are {{competitors}}. Include: brand voice and tone guidelines, core messaging pillars, visual identity direction (colors, typography, imagery), positioning statement, brand personality traits, and a tagline options list (5 options).', true, true, 1),
('marketing-calendar-30-day', '30-Day Marketing Calendar', 'Marketing & Brand Strategy', 'Generate a full month of marketing activities mapped to your goals and channels.', 'Act as a marketing manager. Create a 30-day marketing calendar for {{business_name}}, a {{business_type}}. Our primary goal this month is {{monthly_goal}} and our active channels are {{channels}}. Provide a week-by-week breakdown with specific daily actions, content themes, channel-specific tactics, and KPIs to track. Format as a table.', false, true, 2),
('positioning-statement-generator', 'Positioning Statement Generator', 'Marketing & Brand Strategy', 'Craft a sharp, differentiated positioning statement using proven frameworks.', 'Act as a brand positioning expert. Using the Moore formulation (For [target] who [need], [brand] is [category] that [benefit] unlike [competitors] because [reason]), create 3 positioning statement options for {{business_name}}, which {{business_description}}. Our target customer is {{target_audience}} and our key differentiator is {{differentiator}}. For each option, explain why it works and when to use it.', false, true, 3),
('ideal-customer-avatar', 'Ideal Customer Avatar Profile', 'Marketing & Brand Strategy', 'Build a detailed buyer persona that informs every marketing decision.', 'Act as a consumer research analyst. Create a detailed ideal customer avatar for {{business_name}}, which sells {{product_service}}. Include: demographics (age, location, income, education), psychographics (values, beliefs, lifestyle), pain points (top 5), goals and aspirations, information sources (where they learn, who they trust), typical objections, and a day-in-the-life narrative. Name the avatar and give them a backstory.', true, true, 4),
('competitive-analysis-deep-dive', 'Competitive Analysis Deep Dive', 'Marketing & Brand Strategy', 'Analyze your competitors and find the gaps you can own.', 'Act as a competitive intelligence analyst. Conduct a competitive analysis for {{business_name}} in the {{industry}} industry. Our top competitors are {{competitor_list}}. For each competitor, evaluate: product/service offering, pricing model, marketing channels, brand positioning, strengths, weaknesses, and customer reviews sentiment. Then identify 3 market gaps we could exploit and recommend a differentiation strategy.', false, true, 5),
('brand-story-narrative', 'Brand Story Narrative', 'Marketing & Brand Strategy', 'Tell your brand''s origin story in a way that builds emotional connection.', 'Act as a brand storyteller. Write a compelling brand origin story for {{business_name}}, founded by {{founder_name}}. The business was started because {{origin_reason}}. Our mission is {{mission}}. Write a 400-word narrative in first person that is authentic, emotional, and connects with {{target_audience}}. Include a hook, a struggle, a turning point, and a vision for the future.', false, true, 6),
('launch-campaign-plan', 'Product Launch Campaign Plan', 'Marketing & Brand Strategy', 'Plan a multi-channel launch from teaser to post-launch momentum.', 'Act as a launch strategist. Create a product launch campaign plan for {{product_name}}, which {{product_description}}. The launch date is {{launch_date}} and our budget is {{budget}}. Include: pre-launch teaser phase (2 weeks before), launch week activities, post-launch momentum phase, channel-specific tactics, email sequence outline, content calendar, and success metrics. Our target audience is {{target_audience}}.', true, true, 7),
('messaging-house-framework', 'Messaging House Framework', 'Marketing & Brand Strategy', 'Organize all your messaging into a structured, reusable architecture.', 'Act as a messaging architect. Build a messaging house framework for {{business_name}}, which {{business_description}}. The foundation is our core value proposition: {{value_prop}}. Create: 1 pillars (3-4 key themes), 2 proof points for each pillar, 3 audience-specific message variations for {{audience_segments}}, and 4 elevator pitch versions (15-second, 30-second, 60-second, written).', false, true, 8),
('viral-reel-script', 'Viral Reel Script Writer', 'Social Media & Content', 'Create scroll-stopping short-form video scripts with hooks and CTAs.', 'Act as a short-form video strategist. Write a {{duration}}-second Reel/TikTok script for {{business_name}} about {{topic}}. The hook should be a pattern interrupt in the first 3 seconds. Include: visual directions, on-screen text, voiceover script, trending audio suggestion, and a CTA driving viewers to {{cta_action}}. Provide 3 hook variations so I can A/B test. Our audience is {{target_audience}}.', true, true, 9),
('content-pillar-strategy', 'Content Pillar Strategy', 'Social Media & Content', 'Define 4-5 content pillars and generate a quarter''s worth of post ideas.', 'Act as a content strategist. Design a content pillar strategy for {{business_name}} on {{platforms}}. Our brand voice is {{brand_voice}} and our audience cares about {{audience_interests}}. Define 4-5 content pillars, then generate 8 post ideas per pillar (32 total) with: post type (educational, inspirational, promotional, behind-the-scenes), suggested format, hook line, and caption angle.', false, true, 10),
('caption-that-converts', 'Caption That Converts', 'Social Media & Content', 'Write scroll-stopping captions with proven hook frameworks and CTAs.', 'Act as a social media copywriter. Write 3 caption variations for a post about {{topic}} for {{business_name}} on {{platform}}. Use these hook frameworks: 1) bold statement, 2) question, 3) story lead. Each caption should be {{length}} words, include 5-7 relevant hashtags, and end with a CTA to {{cta_action}}. Our brand voice is {{brand_voice}}.', false, true, 11),
('linkedin-thought-leadership', 'LinkedIn Thought Leadership Post', 'Social Media & Content', 'Position yourself as an authority with nuanced, professional long-form posts.', 'Act as a LinkedIn ghostwriter. Write a thought leadership post for {{author_name}}, who is a {{role}} at {{business_name}}. The post should challenge conventional wisdom about {{topic}}. Use the PAS framework (Problem-Agitate-Solve). Keep it 150-200 words, include a strong opening line, white space for readability, and end with a question to drive comments. Tone: confident, contrarian but respectful.', true, true, 12),
('hashtag-research-strategy', 'Hashtag Research Strategy', 'Social Media & Content', 'Build a tiered hashtag set that balances reach and discoverability.', 'Act as a social media growth strategist. Create a hashtag strategy for {{business_name}} in the {{industry}} niche on {{platform}}. Provide 30 hashtags organized in 3 tiers: 10 high-volume (1M+ posts), 10 medium-volume (100K-1M), 10 niche (under 100K). For each hashtag, explain why it''s relevant to {{target_audience}}. Include a mixing formula for optimal reach.', false, true, 13),
('email-newsletter-welcome-sequence', 'Email Welcome Sequence', 'Social Media & Content', 'Write a 5-email welcome sequence that nurtures new subscribers into fans.', 'Act as an email marketing specialist. Write a 5-email welcome sequence for {{business_name}}''s newsletter. Our lead magnet is {{lead_magnet}} and our audience is {{target_audience}}. Email 1: delivery + introduction. Email 2: origin story. Email 3: best free resource. Email 4: social proof/case study. Email 5: soft pitch for {{product_service}}. For each email provide: subject line, preview text, body copy (150-250 words), and CTA.', true, true, 14),
('blog-post-seo-outline', 'SEO Blog Post Outline', 'Social Media & Content', 'Generate a search-optimized blog outline with headers, keywords, and intent mapping.', 'Act as an SEO content writer. Create a detailed blog post outline for the keyword "{{target_keyword}}" (search intent: {{search_intent}}). Our business is {{business_name}} and our audience is {{target_audience}}. Include: H1 title (click-worthy + keyword), 5-7 H2 sections with 2-3 H3 sub-points each, suggested word count per section, primary and secondary keywords to include, internal linking suggestions, and a meta description (under 160 chars).', false, true, 15),
('social-media-audit', 'Social Media Audit Template', 'Social Media & Content', 'Audit your current social presence and get prioritized improvement actions.', 'Act as a social media consultant. Conduct an audit of {{business_name}}''s social media presence across {{platforms}}. Evaluate: profile completeness, bio clarity, content consistency, engagement rate, visual cohesion, and CTA usage. For each platform, give a score out of 10, identify the top 3 issues, and recommend 5 priority actions for the next 30 days. Our primary goal is {{goal}}.', false, true, 16),
('elevator-pitch-perfector', 'Elevator Pitch Perfecter', 'Sales & Pitching', 'Craft a 30-second pitch that opens doors and sparks curiosity.', 'Act as a sales coach. Write 3 elevator pitch variations for {{business_name}}, which {{business_description}}. Our ideal client is {{ideal_client}} and our key differentiator is {{differentiator}}. Variation 1: problem-solution format. Variation 2: question-led format. Variation 3: story-led format. Each should be under 60 words, end with a hook question, and be conversational (not salesy).', true, true, 17),
('cold-email-that-gets-replies', 'Cold Email That Gets Replies', 'Sales & Pitching', 'Write cold outreach emails with personalization hooks and low-friction CTAs.', 'Act as a B2B sales copywriter. Write a cold email sequence (3 emails) to {{prospect_type}} at {{target_companies}}. My business, {{business_name}}, helps them {{value_delivered}}. Email 1: short, personalized, one ask. Email 2: value-add follow-up with a resource. Email 3: breakup email. For each: subject line (under 6 words), body (under 100 words), and a single low-friction CTA. Avoid buzzwords.', false, true, 18),
('discovery-call-script', 'Discovery Call Script', 'Sales & Pitching', 'Guide a consultative discovery call from opener to next steps.', 'Act as a sales consultant. Create a discovery call script for {{business_name}} selling {{product_service}}. The call is with {{prospect_type}}. Include: rapport-building opener (2 min), agenda set, discovery questions (8-10 open-ended questions organized by theme), active listening prompts, qualification checklist, budget/cost-of-inaction questions, and a next-steps close. Provide estimated time per section for a 30-minute call.', true, true, 19),
('objection-handling-playbook', 'Objection Handling Playbook', 'Sales & Pitching', 'Turn the 5 most common objections into conversion opportunities.', 'Act as a sales trainer. Create an objection handling playbook for {{business_name}} selling {{product_service}} at {{price_point}}. Address the top 5 objections: 1) too expensive, 2) need to think about it, 3) need to talk to {{decision_maker}}, 4) not the right time, 5) already use {{competitor}}. For each: provide the psychological reason behind the objection, a feel-felt-found response, a reframing question, and a pivot to next steps.', false, true, 20),
('sales-page-copy', 'High-Converting Sales Page', 'Sales & Pitching', 'Write a full sales page using proven conversion frameworks.', 'Act as a direct response copywriter. Write a sales page for {{product_name}}, which {{product_description}}. The price is {{price}} and the target buyer is {{target_audience}}. Use this structure: above-the-fold headline + subheadline + CTA, problem agitation, solution introduction, features-to-benefits mapping, social proof section, objection handling, offer stack, risk reversal (guarantee), and final CTA. Write in our brand voice: {{brand_voice}}.', true, true, 21),
('pricing-consultation-script', 'Pricing Consultation Script', 'Sales & Pitching', 'Confidently present pricing and handle price resistance in any conversation.', 'Act as a sales coach. Create a script for presenting pricing for {{product_service}} (priced at {{price}}) to {{prospect_type}}. Include: how to anchor the price, how to frame value before stating the number, language for presenting the investment, responses to "that''s more than I expected," and 3 ways to offer flexible options without discounting. Include do''s and don''ts.', false, true, 22),
('referral-request-templates', 'Referral Request Templates', 'Sales & Pitching', 'Ask for referrals in a way that feels natural and generates warm leads.', 'Act as a relationship-based sales expert. Write 4 referral request templates for {{business_name}} after a successful {{transaction_type}} with {{client_type}}. Template 1: in-person ask. Template 2: email request. Template 3: LinkedIn message. Template 4: post-project thank-you note with a soft ask. For each, explain timing, tone, and the specific phrasing that makes it feel generous (not transactional).', false, true, 23),
('pitch-deck-10-slide', '10-Slide Pitch Deck Outline', 'Sales & Pitching', 'Structure a compelling investor or partner pitch deck slide by slide.', 'Act as a pitch deck consultant. Create a 10-slide pitch deck outline for {{business_name}}, which {{business_description}}. Follow the Sequoia-style structure: 1) Problem, 2) Solution, 3) Market Size, 4) Product, 5) Traction, 6) Business Model, 7) Competition, 8) Team, 9) Financials, 10) The Ask. For each slide, provide: the headline, key bullet points, suggested visual, and speaker notes (what to say, not what''s on the slide).', false, true, 24),
('standard-operating-procedure', 'Standard Operating Procedure Builder', 'Operations & Systems', 'Document any repeatable process into a clear, trainable SOP.', 'Act as an operations manager. Create a Standard Operating Procedure (SOP) for {{process_name}} at {{business_name}}. The person executing this is {{role}} and the current way we do it is {{current_process}}. Format: purpose, scope, prerequisites, step-by-step instructions (numbered), quality checkpoints, troubleshooting guide, and revision log. Make it clear enough that a new hire could follow it on day one.', true, true, 25),
('project-management-plan', 'Project Management Plan', 'Operations & Systems', 'Turn any initiative into a structured project with milestones and owners.', 'Act as a project manager. Create a project plan for {{project_name}} at {{business_name}}. The project goal is {{project_goal}} and the deadline is {{deadline}}. Available team members are {{team_members}}. Include: project scope, work breakdown structure (phases and tasks), task assignments, dependencies, milestone schedule, risk register (top 5 risks with mitigation), and a communication plan.', false, true, 26),
('automation-audit-roadmap', 'Automation Audit & Roadmap', 'Operations & Systems', 'Identify repetitive tasks that can be automated and build an implementation plan.', 'Act as a business automation consultant. Audit {{business_name}}''s operations and identify tasks that can be automated. Our current tools are {{current_tools}} and our biggest time sinks are {{time_sinks}}. For each automation opportunity, provide: the manual process being replaced, recommended tool, setup complexity (low/medium/high), estimated hours saved per month, and a step-by-step implementation guide. Prioritize by impact-to-effort ratio.', true, true, 27),
('team-onboarding-checklist', 'Team Onboarding Checklist', 'Operations & Systems', 'Create a structured first-30-days onboarding plan for any new hire.', 'Act as an HR operations specialist. Create a 30-day onboarding checklist for a new {{role}} joining {{business_name}}. Break it into: pre-arrival (week before), Day 1, Week 1, Week 2, Weeks 3-4. For each phase include: tasks for the manager, tasks for the new hire, training resources to complete, people to meet, and a 30-day check-in agenda. Our team uses {{tools}} and our core values are {{values}}.', false, true, 28),
('customer-journey-map', 'Customer Journey Map', 'Operations & Systems', 'Map every touchpoint from awareness to advocacy and find improvement spots.', 'Act as a CX strategist. Create a customer journey map for {{business_name}}, which {{business_description}}. Map the stages: Awareness, Consideration, Purchase, Onboarding, Usage, Renewal/Repurchase, Advocacy. For each stage include: customer actions, touchpoints, emotions (high/low points), pain points, and opportunities to improve. End with 5 prioritized recommendations.', false, true, 29),
('delegation-framework', 'Delegation Decision Framework', 'Operations & Systems', 'Decide what to delegate, to whom, and how to hand it off cleanly.', 'Act as a leadership coach. Create a delegation framework for {{business_name}}, run by {{owner_name}}. List the owner''s current responsibilities: {{current_tasks}}. For each, evaluate: should it be delegated (using the Eisenhower matrix), who is the right delegate (role, not person), what level of autonomy (tell, sell, consult, agree), what success looks like, and the handoff steps. End with a 90-day delegation rollout plan.', false, true, 30),
('vendor-evaluation-matrix', 'Vendor Evaluation Matrix', 'Operations & Systems', 'Compare vendors objectively with a weighted scoring system.', 'Act as a procurement specialist. Create a vendor evaluation matrix for {{business_name}} choosing a {{vendor_category}}. Our top criteria are {{criteria}} and our shortlisted vendors are {{vendors}}. Build a weighted scoring rubric (weights must total 100%), evaluation questions per criterion, a comparison table template, and a recommendation framework. Include red flags to watch for and negotiation levers.', false, true, 31),
('crisis-response-plan', 'Crisis Response Plan', 'Operations & Systems', 'Prepare for operational disruptions with a clear response protocol.', 'Act as a risk management consultant. Create a crisis response plan for {{business_name}}, which {{business_description}}. Cover these scenarios: {{crisis_scenarios}}. For each, include: early warning signs, immediate response steps (first 24 hours), communication protocol (internal and external), decision-making authority chain, recovery steps, and post-crisis review process. Include a contact tree template.', false, true, 32),
('pricing-strategy-framework', 'Pricing Strategy Framework', 'Finance & Pricing', 'Choose the right pricing model and set prices with confidence.', 'Act as a pricing strategist. Develop a pricing strategy for {{business_name}}, which sells {{product_service}} to {{target_audience}}. Analyze: cost-plus baseline, value-based pricing ceiling, competitor pricing landscape ({{competitors}}), and psychological pricing tactics. Recommend a pricing model (tiered, subscription, bundle, or premium) with 3 specific price points, the rationale for each, and a migration plan from current pricing ({{current_price}}).', true, true, 33),
('revenue-stream-brainstorm', 'Revenue Stream Brainstorm', 'Finance & Pricing', 'Discover new ways to monetize your existing skills and audience.', 'Act as a business model innovator. Brainstorm 10 new revenue stream ideas for {{business_name}}, which currently earns money through {{current_revenue}}. Our audience is {{audience}} and our underutilized assets are {{assets}}. For each idea: describe the offering, estimate the effort to launch (low/med/high), estimate revenue potential (monthly range), identify what''s needed to start, and rate alignment with our brand (1-5). Recommend the top 3 to pursue first.', false, true, 34),
('profit-margin-analyzer', 'Profit Margin Analyzer', 'Finance & Pricing', 'Analyze your margins by product and find where to focus or cut.', 'Act as a fractional CFO. Analyze the profit margins for {{business_name}}''s offerings: {{product_list}}. For each, I have these costs: {{cost_breakdown}} and these prices: {{current_prices}}. Calculate the gross margin and net margin per product, identify the most and least profitable items, recommend pricing or cost adjustments, and suggest which products to sunset, optimize, or scale. Include a simple margin dashboard template.', false, true, 35),
('cash-flow-forecast', '12-Month Cash Flow Forecast', 'Finance & Pricing', 'Project your cash position month by month to plan ahead with clarity.', 'Act as a financial planner. Create a 12-month cash flow forecast for {{business_name}}. Our average monthly revenue is {{monthly_revenue}} and our fixed monthly costs are {{fixed_costs}}. Variable costs are approximately {{variable_costs_percent}}% of revenue. Include: month-by-month projected inflows and outflows, seasonal adjustments (our busy season is {{busy_season}}), a breakeven calculation, a worst-case scenario, and 3 recommendations to improve cash flow.', true, true, 36),
('expense-audit-reduction', 'Expense Audit & Reduction Plan', 'Finance & Pricing', 'Find hidden costs and build a plan to reduce overhead without cutting quality.', 'Act as a cost optimization consultant. Audit {{business_name}}''s expenses and create a reduction plan. Our current monthly expenses are {{expense_list}} totaling {{total_monthly}}. Categorize each as essential, important, or nice-to-have. Identify expenses that can be: eliminated, negotiated down, replaced with cheaper alternatives, or consolidated. Project annual savings and create a 60-day implementation checklist.', false, true, 37),
('financial-dashboard-setup', 'Financial Dashboard Setup', 'Finance & Pricing', 'Define the metrics and KPIs that tell you the real story of your business.', 'Act as a financial analyst. Design a financial dashboard for {{business_name}}, a {{business_type}}. Define the top 10 metrics to track weekly/monthly, categorized as: revenue metrics, profitability metrics, cash metrics, and growth metrics. For each metric: define it, explain why it matters, provide the formula, suggest a target range for our industry ({{industry}}), and recommend how often to review it.', false, true, 38),
('invoice-and-payment-terms', 'Invoice & Payment Terms Optimizer', 'Finance & Pricing', 'Set payment terms that protect your cash flow and reduce late payments.', 'Act as an AR specialist. Optimize the invoicing and payment terms for {{business_name}}, which bills {{client_type}} {{amount_range}} per {{engagement_type}}. Recommend: payment terms (deposit %, milestone payments, net terms), late payment policy, early payment incentives, invoice template structure, and a follow-up sequence for overdue invoices. Include email templates for each follow-up stage.', false, true, 39),
('tax-deduction-checklist', 'Small Business Tax Deduction Checklist', 'Finance & Pricing', 'Get a comprehensive checklist of deductions commonly missed by small businesses.', 'Act as a small business tax advisor. Create a tax deduction checklist for {{business_name}}, a {{business_structure}} in the {{industry}} industry. Organize deductions by category: home office, vehicle, equipment, software, professional development, travel, meals, healthcare, and retirement. For each, note: what qualifies, documentation needed, common mistakes, and special considerations. Include a disclaimer that this is educational and to consult a tax professional.', false, true, 40),
('grant-discovery-and-shortlisting', 'Grant Discovery & Shortlisting', 'Grants & Funding', 'Educational tool to research and shortlist grants that may align with your business. Does not guarantee funding.', 'EDUCATIONAL USE ONLY — This prompt is a research tool to help you identify grants that may align with your business. It does not guarantee funding, awards, or approval. Always verify eligibility and requirements directly with the funding organization. Act as a grants research assistant. Help me identify potential grants for {{business_name}}, a {{business_type}} in the {{industry}} industry. Our business is located in {{location}}, has {{employee_count}} employees, and is {{ownership_demographic}}-owned. Our funding need is {{funding_need}} for {{funding_purpose}}. List 10 potential grants (federal, state, private, corporate) that may align, including: funder name, program name, eligibility highlights, award range, deadline (if known), and a link or where to find more info. Flag any I should verify eligibility for.', true, true, 41),
('grant-eligibility-assessment', 'Grant Eligibility Self-Assessment', 'Grants & Funding', 'Educational checklist to evaluate whether your business likely meets a grant''s criteria. Does not guarantee funding.', 'EDUCATIONAL USE ONLY — This prompt helps you self-assess potential eligibility. It does not guarantee funding or approval. Always confirm requirements with the funder. Act as a grant readiness coach. Create an eligibility self-assessment checklist for the {{grant_name}} from {{funder}}. Their stated criteria are {{stated_criteria}}. My business is {{business_name}}, a {{business_type}} with {{business_details}}. Create a checklist: for each criterion, state the requirement, assess whether my business likely meets it (yes/no/unsure), list evidence I would need, and flag gaps. End with a readiness score and 5 actions to strengthen my application. Remind me to verify everything with the funder.', false, true, 42),
('grant-application-narrative', 'Grant Application Narrative Draft', 'Grants & Funding', 'Educational drafting tool to help you start a compelling narrative. Does not guarantee funding and must be reviewed before submission.', 'EDUCATIONAL USE ONLY — This generates a draft to help you start writing. It does not guarantee funding. Always review with a qualified professional and verify funder requirements before submitting. Act as a grant writing assistant. Help me draft a narrative section for the {{grant_name}} application. The funder''s prompt for this section is: {{section_question}}. My business is {{business_name}} and our proposed use of funds is {{use_of_funds}}. Write a 500-word draft that: addresses the question directly, aligns with the funder''s stated priorities ({{funder_priorities}}), includes measurable outcomes, and tells a compelling story. Mark placeholders where I need to insert specific data. Remind me to verify all requirements with the funder before submitting.', true, true, 43),
('grant-budget-justification', 'Grant Budget Justification Draft', 'Grants & Funding', 'Educational tool to draft a budget justification narrative. Does not guarantee funding; verify all costs with the funder.', 'EDUCATIONAL USE ONLY — This is a drafting tool, not financial advice. It does not guarantee funding. Verify all allowable costs and formats with the funder. Act as a grant budget assistant. Help me draft a budget justification narrative for the {{grant_name}}. My requested budget items are: {{budget_items}} totaling {{total_amount}}. The funder allows costs for {{allowable_categories}}. For each line item, write 2-3 sentences explaining: what it is, why it''s necessary for the project, and how the amount was calculated. End with a summary paragraph tying the budget to project outcomes. Flag any items that may not be allowable and remind me to confirm with the funder.', false, true, 44),
('business-loan-comparison', 'Business Loan Comparison Helper', 'Grants & Funding', 'Educational comparison of loan types to understand your options. Does not guarantee approval or constitute financial advice.', 'EDUCATIONAL USE ONLY — This is for understanding loan options, not financial advice. It does not guarantee loan approval. Consult a financial professional before borrowing. Act as a small business lending educator. Compare loan options for {{business_name}}, which needs {{loan_amount}} for {{loan_purpose}}. Our credit profile is {{credit_profile}} and our time in business is {{time_in_business}}. Compare: SBA 7(a), SBA microloan, term loan, business line of credit, and equipment financing. For each: explain how it works, typical rates, typical terms, collateral requirements, and pros/cons for my situation. This is educational only—recommend I speak with a lender before applying.', false, true, 45),
('investor-pitch-prep', 'Investor Pitch Preparation', 'Grants & Funding', 'Educational tool to prepare for investor conversations. Does not guarantee funding or investment.', 'EDUCATIONAL USE ONLY — This helps you prepare; it does not guarantee investment. Do your own due diligence on any investor. Act as a startup advisor. Help me prepare for an investor pitch for {{business_name}}, which {{business_description}}. We are raising {{raise_amount}} at a {{valuation}} valuation. Our current traction is {{traction}}. Create: a one-line pitch, 5 likely investor questions with suggested answers, 3 metrics to memorize, a competitive landscape framing, and a clear ask. Also list 3 red flags to avoid and 3 due diligence questions I should ask the investor.', true, true, 46),
('grant-research-keywords', 'Grant Research Keyword Builder', 'Grants & Funding', 'Educational tool to build search terms for finding grants. Does not guarantee funding; always verify sources.', 'EDUCATIONAL USE ONLY — This helps you search; it does not guarantee funding. Verify all opportunities with official sources. Act as a grants research librarian. Generate search keywords and phrases to help me find grants for {{business_name}}, a {{business_type}} in {{industry}}. My business is {{ownership_demographic}}-owned and located in {{location}}. Provide: 20 keyword combinations (industry + funding type), 10 niche terms for my demographic, 5 government database search strings, and a list of 8 websites to search. Remind me to verify every opportunity on the official funder site.', false, true, 47),
('funding-readiness-audit', 'Funding Readiness Audit', 'Grants & Funding', 'Educational self-audit of your readiness to apply for funding. Does not guarantee funding or approval.', 'EDUCATIONAL USE ONLY — This self-assessment does not guarantee funding. Always verify requirements with the specific funder and review applications with a qualified professional. Act as a funding readiness coach. Audit {{business_name}}''s readiness to apply for funding (grants or loans). We are a {{business_type}} seeking {{funding_amount}}. Evaluate readiness across: legal structure, financial records, business plan, tax compliance, credit profile, documentation, and narrative materials. For each area: score readiness (1-5), list what''s ready, list what''s missing, and give a priority action. End with an overall readiness score and a 30-day preparation plan.', false, true, 48),
('morning-routine-optimizer', 'Morning Routine Optimizer', 'Personal Development & Mindset', 'Design a morning routine that energizes you and sets up focused work days.', 'Act as a productivity coach. Design a personalized morning routine for {{your_name}}, a {{role}} running {{business_name}}. My current morning challenges are {{challenges}} and my energy is {{energy_pattern}}. I wake up at {{wake_time}} and start work at {{work_start}}. Create a routine that includes: mindset practice, movement, nourishment, and priority-setting. Provide a minute-by-minute timeline, explain the science behind each element, and give a 7-day habit-stacking plan to implement it.', false, true, 49),
('limiting-belief-reframe', 'Limiting Belief Reframe', 'Personal Development & Mindset', 'Identify and reframe the beliefs holding you back from your next level.', 'Act as a mindset coach. Help me reframe limiting beliefs. My role is {{role}} at {{business_name}} and I''m currently facing {{current_challenge}}. The recurring thought holding me back is: "{{limiting_belief}}". Use cognitive reframing: 1) identify the belief''s origin, 2) challenge it with evidence, 3) create 3 empowering alternative beliefs, 4) design a daily affirmation, and 5) give a 30-day behavioral experiment to test the new belief. Be compassionate but direct.', true, true, 50),
('quarterly-goal-setting', 'Quarterly Goal Setting Framework', 'Personal Development & Mindset', 'Set focused 90-day goals that connect daily action to your big vision.', 'Act as a goal-setting coach. Help {{your_name}} set quarterly goals for {{business_name}}. My 12-month vision is {{annual_vision}} and my current priorities are {{current_priorities}}. Use the OKR framework: define 3 objectives (qualitative) and 3 key results each (quantitative). For each objective: explain why it matters, identify the single highest-leverage action, name a likely obstacle and mitigation, and set a weekly check-in question. End with a one-page printable summary.', false, true, 51),
('imposter-syndrome-reset', 'Imposter Syndrome Reset', 'Personal Development & Mindset', 'Recognize imposter syndrome and build an evidence-based confidence practice.', 'Act as a confidence coach. Help me work through imposter syndrome. I am a {{role}} at {{business_name}} and I recently {{trigger_event}}. The feelings I''m experiencing are {{feelings}}. Help me: 1) normalize what I''m feeling, 2) separate feelings from facts, 3) build an evidence file of my competence, 4) reframe self-talk, and 5) create a pre-meeting/presentation confidence ritual. Be validating and practical.', true, true, 52),
('time-audit-and-reallocation', 'Time Audit & Reallocation Plan', 'Personal Development & Mindset', 'Audit where your time goes and reallocate it to high-impact activities.', 'Act as a time management coach. Help {{your_name}} audit and reallocate time. My roles are {{roles}} and my typical week looks like {{typical_week}}. My most important work is {{priority_work}} but I feel like I never have time for it. Create: a time audit template (categorize current hours), an analysis of where time leaks are, a reallocation plan (move hours from low-value to high-value), a daily time-blocking template, and 3 boundary-setting scripts for protecting focus time.', false, true, 53),
('burnout-recovery-plan', 'Burnout Recovery Plan', 'Personal Development & Mindset', 'Recognize burnout signs and build a sustainable recovery and prevention plan.', 'Act as a wellness coach specializing in entrepreneurs. Help {{your_name}} create a burnout recovery plan. My symptoms are {{symptoms}} and they started around {{when_it_started}}. My work situation is {{work_situation}}. Create: a symptom assessment, a 7-day immediate recovery protocol, a 30-day sustainable energy plan, boundary recommendations (work hours, digital, social), and a long-term prevention system with weekly and monthly check-in rituals. Be gentle but actionable.', true, true, 54),
('networking-strategy-introvert', 'Networking Strategy for Introverts', 'Personal Development & Mindset', 'Build a networking approach that plays to introvert strengths, not against them.', 'Act as a professional networking coach. Create a networking strategy for {{your_name}}, an introverted {{role}} at {{business_name}}. My goals are {{networking_goals}} and my networking discomforts are {{discomforts}}. Design an approach that leverages introvert strengths (depth, listening, written communication): recommend 5 low-energy networking tactics, a pre-event prep routine, an in-event script for starting and exiting conversations, and a 48-hour follow-up system. Include 3 online networking strategies.', false, true, 55),
('decision-making-framework', 'Big Decision Framework', 'Personal Development & Mindset', 'Make tough business decisions with a structured, values-aligned process.', 'Act as a decision-making advisor. Help {{your_name}} make a big decision for {{business_name}}. The decision is: {{the_decision}}. The options I''m weighing are {{options}}. My core values are {{values}} and my key constraints are {{constraints}}. Walk me through: 1) clarifying the real question, 2) listing outcomes for each option (best/worst/likely), 3) a values-alignment check, 4) a 10-10-10 analysis (how I''ll feel in 10 minutes, 10 months, 10 years), 5) a reversible-or-not test, and 6) a recommendation framework.', false, true, 56)
